uv run python -c "import numpy as np, pandas as pd; train=pd.read_csv(\"train.csv\"); X=train.drop(columns=[\"target\"]).to_numpy(float); y=train[\"target\"].to_numpy(float); folds=np.array_split(np.arange(len(y)),5); rmse=lambda a,b: float(np.sqrt(np.mean((a-b)**2)));

def standardize(Xtr,Xva):
 mu=Xtr.mean(axis=0); sigma=Xtr.std(axis=0); sigma[sigma==0]=1.0; return (Xtr-mu)/sigma,(Xva-mu)/sigma

def pred_mean(ytr,n):
 return np.full(n,ytr.mean())

def pred_ols(Xtr,ytr,Xva):
 Xtr1=np.c_[np.ones(len(Xtr)),Xtr]; Xva1=np.c_[np.ones(len(Xva)),Xva]; coef,*_=np.linalg.lstsq(Xtr1,ytr,rcond=None); return Xva1@coef

def pred_ridge(Xtr,ytr,Xva,alpha):
 Xtr_s,Xva_s=standardize(Xtr,Xva); Xtr1=np.c_[np.ones(len(Xtr_s)),Xtr_s]; Xva1=np.c_[np.ones(len(Xva_s)),Xva_s]; reg=np.eye(Xtr1.shape[1]); reg[0,0]=0.0; coef=np.linalg.solve(Xtr1.T@Xtr1+alpha*reg,Xtr1.T@ytr); return Xva1@coef

def pred_knn(Xtr,ytr,Xva,k):
 Xtr_s,Xva_s=standardize(Xtr,Xva); preds=np.empty(len(Xva_s));
 for start in range(0,len(Xva_s),200):
  stop=min(start+200,len(Xva_s)); dist=((Xva_s[start:stop,None,:]-Xtr_s[None,:,:])**2).sum(axis=2); nn=np.argpartition(dist,kth=k-1,axis=1)[:,:k]; preds[start:stop]=ytr[nn].mean(axis=1)
 return preds

models=[(\"mean\", lambda Xtr,ytr,Xva: pred_mean(ytr,len(Xva))),(\"ols\", pred_ols)]
models += [(f\"ridge_{alpha:g}\", lambda Xtr,ytr,Xva,a=alpha: pred_ridge(Xtr,ytr,Xva,a)) for alpha in [0.1,1.0,10.0,100.0,1000.0]]
models += [(f\"knn_{k}\", lambda Xtr,ytr,Xva,kk=k: pred_knn(Xtr,ytr,Xva,kk)) for k in [1,3,5,11,21]]
for name,fn in models:
 scores=[]
 for i in range(5):
  va=folds[i]; tr=np.concatenate([folds[j] for j in range(5) if j != i]); pred=fn(X[tr],y[tr],X[va]); scores.append(rmse(y[va],pred))
 print(f\"{name} {np.mean(scores):.6f}\")"
